import{Lt as e,Vt as t,Z as n,_t as r,bt as i,mt as a,vt as o,yt as s}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var c=JSON.parse(`{"title":"在 WPS 中插入参考文献","description":"","frontmatter":{"title":"在 WPS 中插入参考文献","date":"2023-09-22T20:36:31.000Z"},"headers":[],"relativePath":"user-guide/wps-plugin.md","filePath":"wiki/user-guide/wps-plugin.md"}`),l={name:`user-guide/wps-plugin.md`};function u(n,c,l,u,d,f){let p=t(`Badge`),m=t(`NolebaseGitContributors`),h=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[c[2]||=a(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidewps-plugin.md for this page in Markdown format`,-1),c[3]||=a(`h1`,{id:`在-wps-中插入参考文献`,tabindex:`-1`},[s(`在 WPS 中插入参考文献 `),a(`a`,{class:`header-anchor`,href:`#在-wps-中插入参考文献`,"aria-label":`Permalink to “在 WPS 中插入参考文献”`},`​`)],-1),c[4]||=a(`p`,null,`在 WPS 中使用插件参考文献，目前有两种方法：`,-1),a(`ul`,null,[a(`li`,null,[c[0]||=s(`使用普通版本的 WPS，通过 Zotero WPSJS 项目完成参考文献插入 `,-1),i(p,{text:`推荐`})]),c[1]||=a(`li`,null,`使用带有 VBA 的 WPS，运行为 Word 适配的加载项`,-1)]),c[5]||=o(`<h2 id="通过-zotero-wps-js-项目" tabindex="-1">通过 Zotero WPS JS 项目 <a class="header-anchor" href="#通过-zotero-wps-js-项目" aria-label="Permalink to “通过 Zotero WPS JS 项目”">​</a></h2><p>Zotero WPSJS 项目是一个「WPS 文字」的加载项，该加载项利用 WPS 提供的 JavaScript API 从 Zotero 获取引文信息，并写入到 WPS 文档中。</p><p>它最初是由 <a href="https://github.com/tankwyn" target="_blank" rel="noreferrer">@tankwyn</a> 开发并发布在 <a href="https://github.com/tankwyn/WPS-Zotero" target="_blank" rel="noreferrer">tankwyn/WPS-Zotero</a> 的，随后 <a href="https://gitee.com/wangrui5015" target="_blank" rel="noreferrer">@初心不忘</a> 接手了其维护，将修改版本发布在 <a href="https://gitee.com/wangrui5015/Zotero-WPSJS" target="_blank" rel="noreferrer">wangrui5015/Zotero-WPSJS</a>。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>作者初心不忘已经录制了安装视频，请观看视频教程了解安装步骤：</p><ul><li><a href="https://www.bilibili.com/video/BV12SFXeJEJV" target="_blank" rel="noreferrer">macOS</a></li><li><a href="https://www.bilibili.com/video/BV12SFXeJEJV?p=2" target="_blank" rel="noreferrer">Windows</a></li><li><a href="https://www.bilibili.com/video/BV12SFXeJEJV?p=3" target="_blank" rel="noreferrer">Linux</a></li></ul><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>WPS 插件的按钮与 Word 插件类似，具体的操作过程，请参考 <a href="./ms-word-plugin">在 Word 中插入参考文献</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="_1-zotero-不会自动出现" tabindex="-1">1. Zotero 不会自动出现 <a class="header-anchor" href="#_1-zotero-不会自动出现" aria-label="Permalink to “1. Zotero 不会自动出现”">​</a></h3><p>使用中可能点击按钮后，Zotero 的窗口不会自动出现，可以手动点击一下任务栏中的 Zotero 图标，让 Zotero 的窗口跳到最前。</p><h3 id="_2-插件安装后-wps-内不显示-zotero-选项卡" tabindex="-1">2. 插件安装后 WPS 内不显示 Zotero 选项卡 <a class="header-anchor" href="#_2-插件安装后-wps-内不显示-zotero-选项卡" aria-label="Permalink to “2. 插件安装后 WPS 内不显示 Zotero 选项卡”">​</a></h3><p>该部分教程来自与<a href="https://p.kdocs.cn/s/ZPIJCBAABE" target="_blank" rel="noreferrer">官方文档</a></p><p>若安装 Zotero 插件后，打开 WPS 不显示，请按照以下步骤操作：</p><ol><li><p><strong>关闭 WPS Office 的所有程序</strong>（如文字、表格、演示）。</p></li><li><p><strong>找到 Zotero.dotm 文件并复制它：</strong></p><ul><li><strong>对于 Zotero 7 及更新版本：</strong><ul><li>路径通常为： <code>[Zotero安装盘符]:\\Program Files\\Zotero\\integration\\word-for-windows\\</code></li><li>例如，如果您 Zotero 安装在 D 盘，路径则为 <code>D:\\Program Files\\Zotero\\integration\\word-for-windows\\Zotero.dotm</code></li><li>如果您 Zotero 安装在 C 盘，路径则为 <code>C:\\Program Files\\Zotero\\integration\\word-for-windows\\Zotero.dotm</code></li><li><strong>注意：</strong> <code>Program Files</code> 也可能是 <code>Program Files (x86)</code>，取决于您的 Zotero 安装版本（32 位或 64 位）和系统。请检查您的实际安装目录。</li></ul></li><li><strong>对于 Zotero 6 及更早版本：</strong><ul><li>路径通常为： <code>[Zotero安装盘符]:\\Program Files (x86)\\Zotero\\extensions\\zoteroWinWordIntegration@zotero.org\\install\\</code></li><li>例如：<code>C:\\Program Files (x86)\\Zotero\\extensions\\zoteroWinWordIntegration@zotero.org\\install\\Zotero.dotm</code></li></ul></li><li><strong>如何找到 Zotero 安装目录？</strong><ul><li>如果您不确定 Zotero 安装在哪里，可以尝试右键点击 Zotero 桌面快捷方式，选择「打开文件所在位置」来找到 Zotero 的主安装目录，然后根据您的 Zotero 版本进入上述相应的子文件夹。</li></ul></li><li>在上述路径中找到 <code>Zotero.dotm</code> 文件后，选中它并按 <code>Ctrl+C</code> 复制。 <img src="/assets/WPS_Problems.CI-X1HPc.png" alt="image" width="1072" height="190"></li></ul></li><li><p><strong>将 Zotero.dotm 文件粘贴到 WPS 的启动 (startup) 文件夹：</strong></p><ul><li>打开文件资源管理器，在地址栏输入以下路径并按回车键： <code>%APPDATA%\\kingsoft\\wps\\startup</code> 或者，您也可以手动导航到这个路径，它通常是： <code>C:\\Users\\[您的用户名]\\AppData\\Roaming\\kingsoft\\wps\\startup</code> (请将 <code>[您的用户名]</code> 替换为您实际的 Windows 用户名，例如 <code>Administrator</code>, <code>YourName</code> 等。)</li><li><strong>注意：</strong> <code>AppData</code> 文件夹默认是隐藏的。如果您在 <code>C:\\Users\\[您的用户名]\\</code> 目录下看不到 <code>AppData</code> 文件夹，请在文件资源管理器的菜单栏中点击「查看」（或类似选项卡），然后在「显示/隐藏」区域勾选「隐藏的项目」（或类似选项）即可使其显示出来。 <img src="/assets/WPS_Problems-1.CmGFpMaF.png" alt="image" width="1025" height="166"></li><li>在打开的 <code>startup</code> 文件夹内，按 <code>Ctrl+V</code> 粘贴刚刚复制的 <code>Zotero.dotm</code> 文件。</li></ul></li><li><ul><li>重启 WPS，即可看到 Zotero 插件 <img src="/assets/WPS_Problems-2.DcGoWO96.png" alt="image" width="950" height="170"></li></ul></li></ol><h3 id="_3-有多个-zotero-选项卡" tabindex="-1">3. 有多个 Zotero 选项卡 <a class="header-anchor" href="#_3-有多个-zotero-选项卡" aria-label="Permalink to “3. 有多个 Zotero 选项卡”">​</a></h3><p>如果你之前安装把 Word 里的 Zotero 插件强行安装到 WPS，那样出现多个的 Zotero 选项</p><p><img src="/assets/wps-plugin-ui.C-dJZnzZ.png" alt="多个 Zotero 选择" width="770" height="133"></p><p>先打开 <code>C:\\Users\\你的用户名\\AppData\\Roaming\\kingsoft\\wps</code> 目录 (注意用户名换成你自己的)，找到 <code>startup</code> 目录，删掉里面的 <code>zotero.dotm</code> 文件，这个文件是直接从 Zotero 的 Word 插件里复制到 WPS 里，需要 WPS 有 VBA 环境，现在已经不需要了，可以删掉。</p><p><img src="/assets/wps-vba-plugin-install-path.CmrLkXqB.png" alt="WPS 插件安装路径" width="761" height="164"></p><h2 id="通过-vba-使用" tabindex="-1">通过 VBA 使用 <a class="header-anchor" href="#通过-vba-使用" aria-label="Permalink to “通过 VBA 使用”">​</a></h2><p>使用 WPS 的 VBA 插件插入参考这篇：<a href="https://zhuanlan.zhihu.com/p/579975093" target="_blank" rel="noreferrer">完美在 WPS 中使用 Zotero 的方法</a>，该方法这个方法需要依赖 WPS 的 VBA 环境，需要升级到某些付费版本才行（当然也有破解版）。</p>`,22),i(m),i(h)])}var d=n(l,[[`render`,u]]);export{c as __pageData,d as default};